-- Apply after reviewing duplicate/invalid legacy data.
BEGIN;
ALTER TABLE public.vehicles ADD CONSTRAINT vehicle_capacity CHECK (capacity_kg > 0 AND capacity_m3 > 0) NOT VALID;
ALTER TABLE public.vehicles ADD CONSTRAINT vehicle_consumption CHECK (consumption_km_per_l >= 0 AND emissions_per_km >= 0) NOT VALID;
ALTER TABLE public.vehicles ADD CONSTRAINT vehicle_status CHECK (status IN ('available','in_route','maintenance','unavailable')) NOT VALID;
ALTER TABLE public.drivers ADD CONSTRAINT driver_shift CHECK (shift_start < shift_end) NOT VALID;
ALTER TABLE public.drivers ADD CONSTRAINT driver_status CHECK (status IN ('available','in_route','unavailable','resting')) NOT VALID;
ALTER TABLE public.clients ADD CONSTRAINT client_coordinates CHECK (lat BETWEEN -90 AND 90 AND lng BETWEEN -180 AND 180) NOT VALID;
ALTER TABLE public.clients ADD CONSTRAINT client_priority CHECK (priority IN ('high','medium','low')) NOT VALID;
ALTER TABLE public.orders ADD CONSTRAINT order_load CHECK (weight_kg >= 0 AND volume_m3 >= 0) NOT VALID;
ALTER TABLE public.orders ADD CONSTRAINT order_coordinates CHECK (lat BETWEEN -90 AND 90 AND lng BETWEEN -180 AND 180) NOT VALID;
ALTER TABLE public.orders ADD CONSTRAINT order_window CHECK (time_window_start < time_window_end AND pref_time_window_start < pref_time_window_end) NOT VALID;
ALTER TABLE public.orders ADD CONSTRAINT order_status CHECK (status IN ('pending','planned','in_route','delivered','not_delivered','cancelled')) NOT VALID;
ALTER TABLE public.parameters ADD CONSTRAINT parameter_limits CHECK (max_vehicle_capacity_kg > 0 AND max_weight_kg > 0 AND max_volume_m3 > 0 AND average_speed_km_h > 0 AND max_operation_time_h > 0 AND estimated_consumption_km_per_l > 0 AND emission_factor >= 0 AND max_distance_km > 0 AND max_deliveries_per_route > 0) NOT VALID;
ALTER TABLE public.routes ADD CONSTRAINT route_metrics CHECK (total_distance_km >= 0 AND estimated_time_min >= 0 AND emissions_kg_co2 >= 0 AND completed_deliveries >= 0 AND completed_deliveries <= total_deliveries) NOT VALID;
ALTER TABLE public.routes ADD CONSTRAINT route_status CHECK (status IN ('pending','preparing','in_route','finished','with_incidents')) NOT VALID;
CREATE UNIQUE INDEX IF NOT EXISTS uq_vehicles_code ON public.vehicles (code);
CREATE UNIQUE INDEX IF NOT EXISTS uq_vehicles_plate ON public.vehicles (plate);
CREATE UNIQUE INDEX IF NOT EXISTS uq_drivers_dni ON public.drivers (dni);
CREATE UNIQUE INDEX IF NOT EXISTS uq_drivers_license ON public.drivers (license);
CREATE UNIQUE INDEX IF NOT EXISTS uq_orders_code ON public.orders (code);
CREATE UNIQUE INDEX IF NOT EXISTS uq_routes_code ON public.routes (code);
CREATE UNIQUE INDEX IF NOT EXISTS uq_drivers_vehicle_id ON public.drivers (vehicle_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_vehicles_driver_id ON public.vehicles (driver_id);
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_client_id_fkey;
ALTER TABLE public.orders ADD CONSTRAINT orders_client_id_fkey FOREIGN KEY (client_id) REFERENCES public.clients(id) ON DELETE RESTRICT NOT VALID;
ALTER TABLE public.routes ADD CONSTRAINT routes_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES public.drivers(id) ON DELETE RESTRICT NOT VALID;
ALTER TABLE public.routes ADD CONSTRAINT routes_vehicle_id_fkey FOREIGN KEY (vehicle_id) REFERENCES public.vehicles(id) ON DELETE RESTRICT NOT VALID;
ALTER TABLE public.orders ADD CONSTRAINT orders_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES public.drivers(id) ON DELETE RESTRICT NOT VALID;
ALTER TABLE public.drivers ADD CONSTRAINT drivers_vehicle_id_fkey FOREIGN KEY (vehicle_id) REFERENCES public.vehicles(id) ON DELETE SET NULL NOT VALID;
ALTER TABLE public.vehicles ADD CONSTRAINT vehicles_driver_id_fkey FOREIGN KEY (driver_id) REFERENCES public.drivers(id) ON DELETE SET NULL NOT VALID;
CREATE INDEX IF NOT EXISTS orders_driver_id_idx ON public.orders(driver_id);
CREATE INDEX IF NOT EXISTS orders_route_id_idx ON public.orders(route_id);
CREATE INDEX IF NOT EXISTS routes_date_idx ON public.routes(date);
COMMIT;
